import re

def extract_column_names(text):
    multicolumn_names = [
    "Zysk brutto na sprzedaży", "Zysk netto akcjonariuszy większościowych",
        "Przepływy inwestycyjne", "Rzeczowe aktywa trwałe",
    ]

    # Znajdź linię z nagłówkiem kolumny
    match = re.search(r'Dane\s*/\s*Okres\s+(.*)', text)
    if not match:
        return []
    # Pobierz wszystkie linie, które zaczynają się od nazwy (nie są datami, liczbami itp.)
    lines = text.split('\n')
    names = []
    for line in lines:
        # Pomijaj puste linie i linie z datami/okresami
        if line.strip() and not re.match(r'Q\d+ \d{4}|Data raportu', line):
            # Pobierz nazwę z początku linii (do pierwszego tabulatora lub spacji)
            name = line.split('\t')[0].strip()
            # Pomijaj nagłówki i powtarzające się daty
            if name and not re.match(r'\d{2}\.\d{2}\.\d{4}', name):
                names.append(name)

    del_idx = []
    for i in range(len(names)-1):
        for multi_name in multicolumn_names:
            if multi_name.startswith(names[i]) and names[i] + " " + names[i+1] == multi_name:
                names[i] = multi_name
                del_idx.append(i+1)

    for index in sorted(del_idx, reverse=True):
        del names[index]

    return names


